<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue';
const state = ref(null), tab = ref('overview'), filter = ref('all'), selected = ref(null), error = ref(''), notice = ref(''), busy = ref(false), createOpen = ref(false), topic = ref('');
const form = ref({}), dirty = ref(false);
const meta = name => document.querySelector(`meta[name="${name}"]`).content;
const worker = computed(() => state.value?.worker);
const snapshot = computed(() => state.value?.snapshot);
const jobs = computed(() => snapshot.value?.jobs || []);
const canControl = computed(() => worker.value?.online && worker.value?.control_enabled);
const reviews = computed(() => jobs.value.filter(job => job.mode === 'live' && job.status === 'ready'));
const paused = computed(() => jobs.value.filter(job => ['blocked', 'failed'].includes(job.status)));
const active = computed(() => jobs.value.filter(job => ['queued', 'running', 'publishing'].includes(job.status)));
const shown = computed(() => filter.value === 'review' ? reviews.value : filter.value === 'paused' ? paused.value : filter.value === 'active' ? active.value : jobs.value);
const destinations = computed(() => snapshot.value?.monitor?.destinations || []);
const status = job => job.status === 'ready' && job.mode === 'live' ? 'Ready for review' : ({ready:'Ready to watch',running:'In production',publishing:'Publishing',queued:'Queued',published:'Published',blocked:'Needs attention',skipped:'Skipped',failed:'Failed'}[job.status] || job.status);
const date = value => value ? new Intl.DateTimeFormat('en', { dateStyle:'medium', timeStyle:'short', timeZone:'Asia/Singapore' }).format(new Date(value.replace(' ', 'T') + (/Z$|[+-]\d\d:\d\d$/.test(value) ? '' : 'Z'))) : 'Not connected yet';
async function refresh() {
  try {
    const response = await fetch(meta('studio-state'), { headers:{Accept:'application/json'} });
    if (response.status === 401) { location.reload(); return; }
    if (!response.ok) throw new Error('The control room is unavailable. Trying again shortly.');
    state.value = await response.json(); error.value = '';
    if (!dirty.value && snapshot.value) form.value = { ...snapshot.value.settings };
    if (selected.value) {
      const previous=selected.value;
      const current=jobs.value.find(job => job.id === previous.id);
      selected.value=current?{...current,media_url:current.video_sha256===previous.video_sha256&&previous.media_url?previous.media_url:current.media_url}:null;
    }
  } catch (e) { error.value = e.message; }
}
async function send(operation, payload) {
  busy.value = true; error.value = ''; notice.value = '';
  try {
    const response = await fetch(meta('studio-commands'), {method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-Token':meta('csrf-token')},body:JSON.stringify({request_id:crypto.randomUUID(),operation,payload})});
    const result = await response.json(); if (!response.ok) throw new Error(result.message || 'Could not send this request.');
    notice.value = 'Request sent. Your office worker will pick it up shortly.'; await refresh(); return true;
  } catch (e) { error.value = e.message; return false; }
  finally { busy.value = false; }
}
async function act(operation, job) {
  const ok = await send(operation, {id:job.id,fingerprint:operation === 'approve' ? job.review_fingerprint : job.command_fingerprint});
  if (ok) selected.value = null;
}
async function create(mode) { if (await send('create',{mode,topic:topic.value})) { createOpen.value=false; topic.value=''; } }
async function save() { if (await send('settings',{values:form.value})) dirty.value=false; }
function navigate(value, kind='all') { tab.value=value; filter.value=kind; selected.value=null; }
function signout() { document.querySelector('#logout').submit(); }
let timer;
onMounted(() => { refresh(); timer=setInterval(() => {if (!document.hidden) refresh();},10000); });
onUnmounted(() => clearInterval(timer));
</script>

<template>
  <aside class="sidebar"><a class="wordmark" href="#" @click.prevent="navigate('overview')"><span class="brand-icon">✦</span>fact<span>.</span></a><p class="workspace-label">YOUR CONTROL ROOM</p><nav aria-label="Main navigation"><button :class="{current:tab==='overview'}" @click="navigate('overview')"><span>◫</span>Overview</button><button :class="{current:tab==='library'}" @click="navigate('library')"><span>▤</span>Video library <b>{{ jobs.length }}</b></button><button :class="{current:tab==='automation'}" @click="navigate('automation')"><span>✧</span>Automation</button></nav><div class="sidebar-bottom"><span class="status-light" :class="{online:worker?.online}"></span><div>{{ worker?.online ? 'Office connected' : 'Waiting for office' }}<small>Hosted here. Created there.</small></div></div><button class="signout" @click="signout">Sign out ↗</button></aside>
  <main class="main"><header class="topbar"><span>Workspace <i>›</i> <strong>{{ {overview:'Overview',library:'Video library',automation:'Automation'}[tab] }}</strong></span><span class="connection-pill"><span class="status-light" :class="{online:worker?.online}"></span>{{ worker?.online ? 'OFFICE ONLINE' : 'OFFICE OFFLINE' }}</span></header>
    <div class="page"><div v-if="error" class="message error" role="alert">{{ error }}</div><div v-if="notice" class="message success" role="status">{{ notice }}</div>
      <template v-if="tab==='overview'">
        <section class="page-heading"><div><p class="eyebrow">A LITTLE CURIOSITY. A CONNECTED STUDIO.</p><h1>Your stories, from anywhere<span>.</span></h1><p>Your office does the making. You keep the bigger picture.</p></div><button class="button" :disabled="!canControl" @click="createOpen=true">＋ Create a video</button></section>
        <section class="hero"><div class="hero-copy"><p class="eyebrow">YOUR OWN PRODUCTION RHYTHM</p><h2>Less busywork.<br>More wonder.</h2><p>Research, original visuals, narration and a finished film.<br>One workflow, with room for your judgment.</p><button class="button dark" @click="navigate('library','review')">Review your stories <span>↗</span></button></div><div class="hero-illustration" aria-hidden="true"><div class="orbit"></div><div class="poster behind"><span>SCENE / 02</span><div class="planet"></div><strong>A different<br>perspective.</strong><small>THE UNIVERSE, EXPLAINED.</small></div><div class="poster front"><span>● A FACT ORIGINAL</span><div class="sun"></div><strong>Stay<br>curious.</strong><small>SMALL STORIES. BIG IDEAS.</small></div><span class="star">✦</span></div></section>
        <section class="metrics"><button @click="navigate('library','review')"><span>Ready for your review</span><strong>{{ reviews.length }}</strong><small>The final say stays with you</small></button><button @click="navigate('library','active')"><span>In production</span><strong>{{ active.length }}</strong><small>{{ snapshot?.worker ? 'Worker is creating' : 'Your next story is waiting' }}</small></button><button @click="navigate('library','paused')"><span>Need attention</span><strong>{{ paused.length }}</strong><small>Saved progress stays intact</small></button><div><span>Narration characters today</span><strong>{{ (snapshot?.speech_used || 0).toLocaleString() }}<em> / {{ snapshot?.settings?.speech_limit || '—' }}</em></strong><small>Reserved requests, including uncertain calls</small></div></section>
        <section v-if="!worker || !worker.online || !worker.control_enabled" class="panel pairing-panel"><div class="pairing-symbol">↗</div><div><p class="eyebrow">{{ !worker ? 'ONE CONNECTION TO MAKE' : 'YOUR OFFICE WORKER' }}</p><h3>{{ !worker ? 'Connect the office studio.' : !worker.online ? 'Your office machine is offline.' : 'Connected for monitoring.' }}</h3><p>{{ !worker ? 'Pair FACT Studio on the office GPU PC using your private pairing file. Its videos and production status will appear here.' : !worker.online ? 'Keep the office PC awake and the FACT Studio worker running to continue production.' : 'Start the office worker in production mode to accept requests from this dashboard.' }}</p><small>Last check-in: {{ date(worker?.last_seen_at) }}</small></div></section>
        <div class="two-columns"><section class="panel"><div class="panel-heading"><div><h3>Your attention</h3><p>Small checks. A smoother production day.</p></div><span class="pill" :class="{warn:paused.length}">{{ paused.length ? 'Needs a look' : 'Looking ahead' }}</span></div><div class="attention"><button v-if="reviews.length" @click="navigate('library','review')"><span class="pill">Review</span><span>{{ reviews.length }} original {{ reviews.length===1 ? 'story is' : 'stories are' }} ready for you.</span>→</button><button v-for="issue in (snapshot?.monitor?.issues || []).filter(i=>!['review','blocked'].includes(i.kind))" :key="issue.message" @click="tab='automation'"><span class="pill warn">{{ issue.kind }}</span><span>{{ issue.message }}</span>→</button><p v-if="!snapshot">Your studio's setup checks will appear after the office connects.</p><button v-if="paused.length" @click="navigate('library','paused')"><span class="pill warn">Paused</span><span>{{ paused.length }} videos need attention.</span>→</button><p v-if="snapshot && !snapshot.monitor?.issues?.length && !reviews.length && !paused.length">Nothing needs attention right now.</p></div></section><section class="panel"><div class="panel-heading"><div><h3>The latest requests</h3><p>Sent here. Handled by your office.</p></div></div><div class="command-list"><div v-for="command in (state?.commands || []).slice(0,5)" :key="command.id"><span class="pill" :class="{warn:['failed','expired'].includes(command.state)}">{{ command.state }}</span><div><strong>{{ {create:'Create a story',approve:'Approve and publish',retry:'Resume production',cancel:'Skip a video',settings:'Update automation'}[command.operation] }}</strong><p>{{ command.result || 'Waiting for the office worker.' }}</p></div></div><p v-if="!state?.commands?.length">Your requests will appear here.</p></div></section></div>
        <section class="library-section"><div class="section-heading"><div><h3>Fresh from the studio</h3><p>The latest stories in your library.</p></div><button class="text-button" @click="navigate('library')">View library ↗</button></div><div v-if="jobs.length" class="video-grid"><button v-for="job in jobs.slice(0,3)" :key="job.id" class="video-card" @click="selected=job"><div class="video-thumb"><span>✦</span><small>{{ job.mode==='live' ? 'A FACT ORIGINAL' : 'PREVIEW' }}</small><b>{{ job.data?.video ? Math.round(job.data.video.duration)+' SEC' : 'IN PRODUCTION' }}</b></div><div class="video-info"><h4>{{ job.title }}</h4><span class="pill" :class="{warn:job.status==='blocked'}">{{ status(job) }}</span></div></button></div><div v-else class="empty panel"><span>✧</span><h3>Every story starts somewhere.</h3><p>Your office studio's videos will appear here when connected.</p></div></section>
      </template>
      <template v-else-if="tab==='library'"><section class="page-heading"><div><p class="eyebrow">THE STORIES YOU MAKE</p><h1>Your video library<span>.</span></h1><p>Watch the finished film. Check its sources. Choose what goes out.</p></div><button class="button" :disabled="!canControl" @click="createOpen=true">＋ Create a video</button></section><div class="filters"><button v-for="[value,label] in [['all','All videos'],['review','To review'],['active','In production'],['paused','Needs attention']]" :key="value" :class="{current:filter===value}" @click="filter=value">{{ label }}</button><small>{{ shown.length }} videos</small></div><div v-if="shown.length" class="video-grid"><button v-for="job in shown" :key="job.id" class="video-card" @click="selected=job"><div class="video-thumb"><span>✦</span><small>{{ job.mode==='live' ? 'A FACT ORIGINAL' : 'PREVIEW' }}</small><b>{{ job.data?.video ? Math.round(job.data.video.duration)+' SEC' : 'IN PRODUCTION' }}</b></div><div class="video-info"><h4>{{ job.title }}</h4><span class="pill" :class="{warn:['blocked','ready'].includes(job.status)}">{{ status(job) }}</span></div></button></div><div v-else class="empty panel"><span>✧</span><h3>A little room for the next story.</h3><p>There are no videos in this view yet.</p></div></template>
      <template v-else><section class="page-heading"><div><p class="eyebrow">A ROUTINE FOR YOUR CURIOSITY</p><h1>Keep the stories coming<span>.</span></h1><p>Set the direction. Let your office studio do the making.</p></div><span class="pill">{{ snapshot?.settings?.schedule_enabled==='1' ? 'Daily schedule on' : 'Schedule off' }}</span></section><form class="automation-form" @submit.prevent="save" @input="dirty=true"><div class="two-columns"><section class="panel form-panel"><h3>Your creative direction</h3><label>Story direction<input v-model="form.niche" required maxlength="300"></label><label>Target duration<select v-model="form.duration"><option value="30">30 seconds</option><option value="40">40 seconds</option><option value="45">45 seconds</option><option value="60">60 seconds</option></select></label><label>Daily video cap<select v-model="form.daily_limit"><option value="1">1 video</option><option value="2">2 videos</option><option value="3">3 videos</option></select></label><label>Daily production time<input v-model="form.publish_time" type="time" required></label><small>Production uses the office studio's Asia/Manila schedule (UTC+8).</small><label>Daily ElevenLabs character cap<input v-model="form.speech_limit" type="number" min="0" max="20000" step="100" required></label></section><section class="panel form-panel"><h3>Your production rhythm</h3><label class="switch-row"><span><strong>Daily production</strong><small>Queue one original video each day.</small></span><input v-model="form.schedule_enabled" type="checkbox" true-value="1" false-value="0"></label><label class="switch-row"><span><strong>Review before publishing</strong><small>Finished videos wait for your approval.</small></span><input v-model="form.review_required" type="checkbox" true-value="1" false-value="0"></label><label class="switch-row"><span><strong>Automatic publishing</strong><small>Publish automatically when review is off.</small></span><input v-model="form.auto_publish" type="checkbox" true-value="1" false-value="0"></label><div class="automation-note"><span>✧</span><p>Account connections stay on your office machine. Your existing ElevenLabs, YouTube and Meta settings are used for production.</p></div><h4>Selected destinations</h4><p v-if="!destinations.length" class="muted">Choose destinations in the office studio's Connections screen.</p><p v-for="destination in destinations" :key="destination.platform">{{ destination.label }} <span class="pill">{{ destination.visibility }}</span></p></section></div><div class="form-footer"><p>Changes take effect when the office worker receives them.</p><button class="button" :disabled="!canControl || busy" type="submit">Save automation ✓</button></div></form></template>
      <footer class="footer"><span><b>fact.</b> A space for the stories worth telling.</span><span>HOSTED CONTROL · OFFICE CREATION</span></footer>
    </div></main>
  <div v-if="selected" class="modal-backdrop" @click.self="selected=null"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="video-title"><div class="modal-top"><span class="eyebrow">INSIDE THE STORY</span><button aria-label="Close video details" @click="selected=null">×</button></div><div class="video-detail"><div><video v-if="selected.media_url" :key="selected.media_url" :src="selected.media_url" controls playsinline preload="metadata"></video><div v-else class="video-pending">{{ selected.data?.video ? 'Preview is syncing from the office.' : 'Your film is in production.' }}</div></div><div><span class="pill">{{ status(selected) }}</span><h2 id="video-title">{{ selected.title }}</h2><p v-if="selected.error" class="message error">{{ selected.error }}</p><p v-if="selected.mode!=='live'" class="muted">A preview for checking the creative direction. Previews cannot publish.</p><div class="detail-actions"><a v-if="selected.media_url" class="button secondary" :href="selected.media_url" target="_blank" rel="noopener">Open MP4 ↗</a><button v-if="selected.mode==='live' && ['ready','blocked'].includes(selected.status) && selected.review_fingerprint && !selected.publication_started" class="button" :disabled="!canControl || busy || !selected.media_url || !destinations.length" @click="act('approve',selected)">Approve &amp; publish</button><button v-if="selected.status==='blocked'" class="button secondary" :disabled="!canControl || busy" @click="act('retry',selected)">Retry job</button><button v-if="['ready','queued','blocked'].includes(selected.status)" class="text-button" :disabled="!canControl || busy" @click="act('cancel',selected)">Skip video</button></div><div v-if="selected.mode==='live' && ['ready','blocked'].includes(selected.status)" class="review-note"><strong>Watch the film before approving.</strong><p>Approval sends this saved video to:</p><p v-for="destination in destinations" :key="destination.platform">{{ destination.label }} <span class="pill">{{ destination.visibility }}</span></p><small>Saved narration and video are reused.</small></div><h4>The narration</h4><p class="narration">{{ selected.narration || 'The script will appear here when it is ready.' }}</p><h4>Source material</h4><a v-for="source in selected.sources" :key="source.url" class="source-link" :href="source.url" target="_blank" rel="noopener noreferrer">{{ source.title }} ↗</a></div></div></section></div>
  <div v-if="createOpen" class="modal-backdrop" @click.self="createOpen=false"><section class="modal create-modal" role="dialog" aria-modal="true" aria-labelledby="create-title"><div class="modal-top"><span class="eyebrow">LET'S MAKE SOMETHING</span><button aria-label="Close new video" @click="createOpen=false">×</button></div><h2 id="create-title">One idea. A new story.</h2><p>The office studio can choose a fresh NASA story, or you can give it a direction.</p><label>Optional story angle<input v-model="topic" maxlength="300" placeholder="Something surprising about our solar system"></label><p class="muted">Original production uses your ElevenLabs credits. A free AI preview uses the office Windows voice and never publishes.</p><div class="detail-actions"><button class="button" :disabled="busy || !canControl" @click="create('live')">Start production →</button><button class="button secondary" :disabled="busy || !canControl" @click="create('preview')">Free AI preview</button></div></section></div>
</template>
